import type { Session, User, UserRole } from '../types';

export const AUTH_STORAGE_KEY = 'sissy-training-auth';

export const DEFAULT_ADMIN_USERNAME = 'admin';
export const DEFAULT_ADMIN_PASSWORD = 'changeme';

export interface AuthData {
  users: User[];
  session: Session | null;
}

export async function hashPassword(password: string): Promise<string> {
  const data = new TextEncoder().encode(password);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(hash)]
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

export function loadAuth(): AuthData {
  try {
    const raw = localStorage.getItem(AUTH_STORAGE_KEY);
    if (!raw) return { users: [], session: null };
    const parsed = JSON.parse(raw) as AuthData;
    return {
      users: parsed.users ?? [],
      session: parsed.session ?? null,
    };
  } catch {
    return { users: [], session: null };
  }
}

export function saveAuth(data: AuthData): void {
  localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(data));
}

export async function ensureDefaultAdmin(): Promise<AuthData> {
  const auth = loadAuth();
  if (auth.users.length > 0) return auth;

  const admin: User = {
    id: 'user-admin',
    username: DEFAULT_ADMIN_USERNAME,
    passwordHash: await hashPassword(DEFAULT_ADMIN_PASSWORD),
    role: 'admin',
  };

  const next = { users: [admin], session: null };
  saveAuth(next);
  return next;
}

export async function login(
  username: string,
  password: string,
): Promise<{ ok: true; session: Session } | { ok: false; error: string }> {
  const auth = loadAuth();
  const user = auth.users.find(
    (u) => u.username.toLowerCase() === username.trim().toLowerCase(),
  );
  if (!user) {
    return { ok: false, error: 'Invalid username or password.' };
  }

  const hash = await hashPassword(password);
  if (hash !== user.passwordHash) {
    return { ok: false, error: 'Invalid username or password.' };
  }

  const session: Session = {
    userId: user.id,
    username: user.username,
    role: user.role,
  };

  saveAuth({ ...auth, session });
  return { ok: true, session };
}

export function logout(): void {
  const auth = loadAuth();
  saveAuth({ ...auth, session: null });
}

export async function changePassword(
  userId: string,
  currentPassword: string,
  newPassword: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  if (newPassword.length < 6) {
    return { ok: false, error: 'New password must be at least 6 characters.' };
  }

  const auth = loadAuth();
  const user = auth.users.find((u) => u.id === userId);
  if (!user) {
    return { ok: false, error: 'User not found.' };
  }

  const currentHash = await hashPassword(currentPassword);
  if (currentHash !== user.passwordHash) {
    return { ok: false, error: 'Current password is incorrect.' };
  }

  const updated: User = {
    ...user,
    passwordHash: await hashPassword(newPassword),
  };

  const users = auth.users.map((u) => (u.id === userId ? updated : u));
  saveAuth({ users, session: auth.session });
  return { ok: true };
}

export async function createUser(
  username: string,
  password: string,
  role: UserRole,
): Promise<{ ok: true; user: User } | { ok: false; error: string }> {
  const trimmed = username.trim();
  if (!trimmed) {
    return { ok: false, error: 'Username is required.' };
  }
  if (password.length < 6) {
    return { ok: false, error: 'Password must be at least 6 characters.' };
  }

  const auth = loadAuth();
  if (
    auth.users.some((u) => u.username.toLowerCase() === trimmed.toLowerCase())
  ) {
    return { ok: false, error: 'Username already exists.' };
  }

  const user: User = {
    id: `user-${Date.now()}`,
    username: trimmed,
    passwordHash: await hashPassword(password),
    role,
  };

  saveAuth({ ...auth, users: [...auth.users, user] });
  return { ok: true, user };
}

