import { FormEvent, useState } from 'react';
import { Navigate, useLocation, useNavigate } from 'react-router-dom';
import { useAppStore } from '../hooks/useAppStore';
import { DEFAULT_ADMIN_PASSWORD, DEFAULT_ADMIN_USERNAME } from '../lib/auth';

export function Login() {
  const { session, authReady, login } = useAppStore();
  const navigate = useNavigate();
  const location = useLocation();
  const from =
    (location.state as { from?: string } | null)?.from ?? '/';

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  if (authReady && session) {
    return <Navigate to={from} replace />;
  }

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setSubmitting(true);
    const result = await login(username, password);
    setSubmitting(false);
    if (result.ok) {
      navigate(from, { replace: true });
    } else {
      setError(result.error);
    }
  };

  return (
    <div className="login-page">
      <motionless className="login-card card">
        <h1 className="app-title">Sissy Training</h1>
        <p className="app-tagline">Sign in to continue</p>

        <form className="login-form" onSubmit={handleSubmit}>
          <label className="field">
            <span>Username</span>
            <input
              type="text"
              autoComplete="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Username"
              required
            />
          </label>
          <label className="field">
            <span>Password</span>
            <input
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Password"
              required
            />
          </label>

          {error && <p className="login-error" role="alert">{error}</p>}

          <button
            type="submit"
            className="btn btn--primary btn--block"
            disabled={submitting}
          >
            {submitting ? 'Signing in…' : 'Sign in'}
          </button>
        </form>

        <p className="muted login-hint">
          First install? Default admin: <strong>{DEFAULT_ADMIN_USERNAME}</strong>{' '}
          / <strong>{DEFAULT_ADMIN_PASSWORD}</strong>. Change your password in
          Settings after signing in.
        </p>
      </motionless>
    </div>
  );
}

import { useState } from 'react';
import { Link } from 'react-router-dom';
import type { Category, Task, TaskFrequency, UserRole } from '../types';
import { useAppStore } from '../hooks/useAppStore';

function newId(prefix: string): string {
  return `${prefix}-${Date.now()}`;
}

export function Admin() {
  const [tab, setTab] = useState<'categories' | 'tasks' | 'users'>('categories');

  return (
    <div className="page">
      <header className="page-header">
        <h2>Admin</h2>
        <p className="muted">Manage categories, tasks, and users</p>
      </header>

      <div className="tabs">
        <button
          type="button"
          className={tab === 'categories' ? 'tab tab--active' : 'tab'}
          onClick={() => setTab('categories')}
        >
          Categories
        </button>
        <button
          type="button"
          className={tab === 'tasks' ? 'tab tab--active' : 'tab'}
          onClick={() => setTab('tasks')}
        >
          Tasks
        </button>
        <button
          type="button"
          className={tab === 'users' ? 'tab tab--active' : 'tab'}
          onClick={() => setTab('users')}
        >
          Users
        </button>
      </motionless>

      {tab === 'categories' && <CategoryAdmin />}
      {tab === 'tasks' && <TaskAdmin />}
      {tab === 'users' && <UserAdmin />}

      <p className="muted">
        <Link to="/settings">Back to settings</Link>
      </p>
    </div>
  );
}

function CategoryAdmin() {
  const { state, addCategory, updateCategory, deleteCategory } = useAppStore();
  const [draft, setDraft] = useState<Category>({
    id: '',
    name: '',
    icon: '✨',
    color: '#f9a8d4',
    description: '',
  });
  const [message, setMessage] = useState('');

  const submit = () => {
    if (!draft.name.trim()) return;
    const cat = { ...draft, id: draft.id || newId('cat') };
    if (state.categories.some((c) => c.id === cat.id)) updateCategory(cat);
    else addCategory(cat);
    setDraft({ id: '', name: '', icon: '✨', color: '#f9a8d4', description: '' });
    setMessage('Category saved.');
  };

  const remove = (id: string) => {
    if (!window.confirm('Delete this category and all its tasks?')) return;
    deleteCategory(id);
    if (draft.id === id) {
      setDraft({ id: '', name: '', icon: '✨', color: '#f9a8d4', description: '' });
    }
    setMessage('Category deleted.');
  };

  return (
    <section className="card">
      {message && <p className="notice">{message}</p>}
      <ul className="edit-list">
        {state.categories.length === 0 && (
          <li className="muted">No categories yet. Create one below.</li>
        )}
        {state.categories.map((c) => (
          <li key={c.id} className="edit-list__row">
            <button
              type="button"
              className="edit-list__btn"
              onClick={() => setDraft(c)}
            >
              {c.icon} {c.name}
            </button>
            <button
              type="button"
              className="btn btn--ghost btn--small"
              onClick={() => remove(c.id)}
            >
              Delete
            </button>
          </li>
        ))}
      </ul>
      <div className="form-grid">
        <input
          placeholder="Name"
          value={draft.name}
          onChange={(e) => setDraft({ ...draft, name: e.target.value })}
        />
        <input
          placeholder="Icon (emoji)"
          value={draft.icon}
          onChange={(e) => setDraft({ ...draft, icon: e.target.value })}
        />
        <input
          type="color"
          aria-label="Category color"
          value={draft.color}
          onChange={(e) => setDraft({ ...draft, color: e.target.value })}
        />
        <input
          placeholder="Description"
          value={draft.description}
          onChange={(e) => setDraft({ ...draft, description: e.target.value })}
        />
      </div>
      <button type="button" className="btn btn--primary" onClick={submit}>
        {draft.id ? 'Update category' : 'Create category'}
      </button>
    </section>
  );
}

function TaskAdmin() {
  const { state, addTask, updateTask, deleteTask } = useAppStore();
  const [draft, setDraft] = useState<Task>({
    id: '',
    title: '',
    description: '',
    categoryId: '',
    minLevel: 1,
    xpReward: 10,
    frequency: 'daily',
  });
  const [message, setMessage] = useState('');

  const submit = () => {
    if (!draft.title.trim()) return;
    if (!draft.categoryId) {
      setMessage('Select a category first.');
      return;
    }
    const task = { ...draft, id: draft.id || newId('task') };
    if (state.tasks.some((t) => t.id === task.id)) updateTask(task);
    else addTask(task);
    setDraft({
      id: '',
      title: '',
      description: '',
      categoryId: state.categories[0]?.id ?? '',
      minLevel: 1,
      xpReward: 10,
      frequency: 'daily',
    });
    setMessage('Task saved.');
  };

  const remove = (id: string) => {
    if (!window.confirm('Delete this task?')) return;
    deleteTask(id);
    if (draft.id === id) {
      setDraft({
        id: '',
        title: '',
        description: '',
        categoryId: state.categories[0]?.id ?? '',
        minLevel: 1,
        xpReward: 10,
        frequency: 'daily',
      });
    }
    setMessage('Task deleted.');
  };

  if (state.categories.length === 0) {
    return (
      <section className="card">
        <p className="muted">Create at least one category before adding tasks.</p>
      </section>
    );
  }

  return (
    <section className="card">
      {message && <p className="notice">{message}</p>}
      <ul className="edit-list">
        {state.tasks.length === 0 && (
          <li className="muted">No tasks yet. Create one below.</li>
        )}
        {state.tasks.map((t) => (
          <li key={t.id} className="edit-list__row">
            <button
              type="button"
              className="edit-list__btn"
              onClick={() => setDraft(t)}
            >
              {t.title}
            </button>
            <button
              type="button"
              className="btn btn--ghost btn--small"
              onClick={() => remove(t.id)}
            >
              Delete
            </button>
          </li>
        ))}
      </ul>
      <motionless className="form-grid">
        <input
          placeholder="Title"
          value={draft.title}
          onChange={(e) => setDraft({ ...draft, title: e.target.value })}
        />
        <input
          placeholder="Description"
          value={draft.description}
          onChange={(e) => setDraft({ ...draft, description: e.target.value })}
        />
        <select
          value={draft.categoryId || state.categories[0]?.id}
          onChange={(e) => setDraft({ ...draft, categoryId: e.target.value })}
          aria-label="Category"
        >
          {state.categories.map((c) => (
            <option key={c.id} value={c.id}>
              {c.icon} {c.name}
            </option>
          ))}
        </select>
        <input
          type="number"
          min={1}
          max={5}
          aria-label="Minimum level"
          value={draft.minLevel}
          onChange={(e) => setDraft({ ...draft, minLevel: Number(e.target.value) })}
        />
        <input
          type="number"
          min={5}
          aria-label="XP reward"
          value={draft.xpReward}
          onChange={(e) => setDraft({ ...draft, xpReward: Number(e.target.value) })}
        />
        <select
          value={draft.frequency}
          onChange={(e) =>
            setDraft({ ...draft, frequency: e.target.value as TaskFrequency })
          }
          aria-label="Frequency"
        >
          <option value="daily">Daily</option>
          <option value="weekly">Weekly</option>
          <option value="once">One-time</option>
        </select>
        <input
          type="number"
          min={1}
          placeholder="Duration (minutes, optional)"
          value={draft.durationMinutes ?? ''}
          onChange={(e) =>
            setDraft({
              ...draft,
              durationMinutes: e.target.value ? Number(e.target.value) : undefined,
            })
          }
        />
      </motionless>
      <button type="button" className="btn btn--primary" onClick={submit}>
        {draft.id ? 'Update task' : 'Create task'}
      </button>
    </section>
  );
}

function UserAdmin() {
  const { createAppUser } = useAppStore();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState<UserRole>('user');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const submit = async () => {
    setError('');
    setMessage('');
    const result = await createAppUser(username, password, role);
    if (result.ok) {
      setMessage(`User "${result.user.username}" created.`);
      setUsername('');
      setPassword('');
    } else {
      setError(result.error);
    }
  };

  return (
    <section className="card">
      <p className="muted">Create accounts for regular users or additional admins.</p>
      <div className="form-grid">
        <input
          placeholder="Username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <input
          type="password"
          placeholder="Password (min 6 characters)"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <select
          value={role}
          onChange={(e) => setRole(e.target.value as UserRole)}
          aria-label="Role"
        >
          <option value="user">User</option>
          <option value="admin">Admin</option>
        </select>
      </div>
      {error && <p className="login-error" role="alert">{error}</p>}
      {message && <p className="notice">{message}</p>}
      <button type="button" className="btn btn--primary" onClick={submit}>
        Create user
      </button>
    </section>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import type { AppState, Category, Session, Task, User, UserRole } from '../types';
import {
  changePassword,
  createUser,
  ensureDefaultAdmin,
  loadAuth,
  login as authLogin,
  logout as authLogout,
  saveAuth,
  type AuthData,
} from '../lib/auth';
import {
  closeDay,
  completeTask,
  dismissPunishment,
  ensureDailyPlan,
  processDayRollover,
  purchaseReward,
  uncompleteTask,
} from '../lib/gameLogic';
import { loadState, resetState, saveState } from '../lib/storage';

interface AppStoreValue {
  state: AppState;
  session: Session | null;
  authReady: boolean;
  refresh: () => void;
  login: (
    username: string,
    password: string,
  ) => Promise<{ ok: true } | { ok: false; error: string }>;
  logout: () => void;
  changePassword: (
    currentPassword: string,
    newPassword: string,
  ) => Promise<{ ok: true } | { ok: false; error: string }>;
  createAppUser: (
    username: string,
    password: string,
    role: UserRole,
  ) => Promise<{ ok: true; user: User } | { ok: false; error: string }>;
  completeTask: (taskId: string) => void;
  uncompleteTask: (taskId: string) => void;
  closeDay: () => void;
  purchaseReward: (rewardId: string) => void;
  dismissPunishment: (id: string) => void;
  updateSettings: (partial: Partial<AppState['settings']>) => void;
  updateCategory: (category: Category) => void;
  addCategory: (category: Category) => void;
  deleteCategory: (id: string) => void;
  updateTask: (task: Task) => void;
  addTask: (task: Task) => void;
  deleteTask: (id: string) => void;
  resetAll: () => void;
}

const AppStoreContext = createContext<AppStoreValue | null>(null);

export function AppStoreProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AppState>(() => loadState());
  const [auth, setAuth] = useState<AuthData>({ users: [], session: null });
  const [authReady, setAuthReady] = useState(false);

  const persist = useCallback((next: AppState) => {
    setState(next);
    saveState(next);
  }, []);

  useEffect(() => {
    void (async () => {
      const initialAuth = await ensureDefaultAdmin();
      setAuth(initialAuth);
      setAuthReady(true);
    })();
  }, []);

  useEffect(() => {
    if (!authReady) return;
    let s = processDayRollover(loadState());
    s = ensureDailyPlan(s);
    persist(s);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- init rollover once
  }, [authReady]);

  const refresh = useCallback(() => {
    let s = loadState();
    s = processDayRollover(s);
    s = ensureDailyPlan(s);
    persist(s);
  }, [persist]);

  const value = useMemo<AppStoreValue>(
    () => ({
      state,
      session: auth.session,
      authReady,
      refresh,
      login: async (username, password) => {
        const result = await authLogin(username, password);
        if (!result.ok) return result;
        setAuth(loadAuth());
        return { ok: true };
      },
      logout: () => {
        authLogout();
        setAuth(loadAuth());
      },
      changePassword: async (currentPassword, newPassword) => {
        if (!auth.session) {
          return { ok: false, error: 'Not signed in.' };
        }
        const result = await changePassword(
          auth.session.userId,
          currentPassword,
          newPassword,
        );
        if (result.ok) setAuth(loadAuth());
        return result;
      },
      createAppUser: async (username, password, role) => {
        const result = await createUser(username, password, role);
        if (result.ok) setAuth(loadAuth());
        return result;
      },
      completeTask: (taskId) => persist(completeTask(state, taskId)),
      uncompleteTask: (taskId) => persist(uncompleteTask(state, taskId)),
      closeDay: () => persist(closeDay(state)),
      purchaseReward: (rewardId) => persist(purchaseReward(state, rewardId)),
      dismissPunishment: (id) => persist(dismissPunishment(state, id)),
      updateSettings: (partial) =>
        persist({ ...state, settings: { ...state.settings, ...partial } }),
      updateCategory: (category) =>
        persist({
          ...state,
          categories: state.categories.map((c) =>
            c.id === category.id ? category : c,
          ),
        }),
      addCategory: (category) =>
        persist({ ...state, categories: [...state.categories, category] }),
      deleteCategory: (id) =>
        persist({
          ...state,
          categories: state.categories.filter((c) => c.id !== id),
          tasks: state.tasks.filter((t) => t.categoryId !== id),
        }),
      updateTask: (task) =>
        persist({
          ...state,
          tasks: state.tasks.map((t) => (t.id === task.id ? task : t)),
        }),
      addTask: (task) => persist({ ...state, tasks: [...state.tasks, task] }),
      deleteTask: (id) =>
        persist({
          ...state,
          tasks: state.tasks.filter((t) => t.id !== id),
          dailyPlans: Object.fromEntries(
            Object.entries(state.dailyPlans).map(([date, plan]) => [
              date,
              {
                ...plan,
                tasks: plan.tasks.filter((pt) => pt.taskId !== id),
                extraTaskIds: plan.extraTaskIds.filter((tid) => tid !== id),
              },
            ]),
          ),
        }),
      resetAll: () => persist(resetState()),
    }),
    [state, auth.session, authReady, persist, refresh],
  );

  return (
    <AppStoreContext.Provider value={value}>{children}</AppStoreContext.Provider>
  );
}

export function useAppStore(): AppStoreValue {
  const ctx = useContext(AppStoreContext);
  if (!ctx) throw new Error('useAppStore must be used within AppStoreProvider');
  return ctx;
}

import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import { AdminRoute } from './components/AdminRoute';
import { Layout } from './components/Layout';
import { ProtectedRoute } from './components/ProtectedRoute';
import { AppStoreProvider } from './hooks/useAppStore';
import { Admin } from './pages/Admin';
import { Dashboard } from './pages/Dashboard';
import { Library } from './pages/Library';
import { Login } from './pages/Login';
import { Punishments } from './pages/Punishments';
import { Rewards } from './pages/Rewards';
import { Settings } from './pages/Settings';
import { Today } from './pages/Today';

export default function App() {
  return (
    <AppStoreProvider>
      <BrowserRouter>
        <Routes>
          <Route path="/login" element={<Login />} />
          <Route element={<ProtectedRoute />}>
            <Route element={<Layout />}>
              <Route index element={<Dashboard />} />
              <Route path="today" element={<Today />} />
              <Route path="library" element={<Library />} />
              <Route path="rewards" element={<Rewards />} />
              <Route path="punishments" element={<Punishments />} />
              <Route path="settings" element={<Settings />} />
            </Route>
            <Route element={<AdminRoute />}>
              <Route path="admin" element={<Admin />} />
            </Route>
          </Route>
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </BrowserRouter>
    </AppStoreProvider>
  );
}

import { FormEvent, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAppStore } from '../hooks/useAppStore';

export function Settings() {
  const {
    state,
    session,
    updateSettings,
    resetAll,
    logout,
    changePassword,
  } = useAppStore();

  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMessage, setPasswordMessage] = useState('');
  const [passwordError, setPasswordError] = useState('');

  const handlePasswordChange = async (e: FormEvent) => {
    e.preventDefault();
    setPasswordMessage('');
    setPasswordError('');
    if (newPassword !== confirmPassword) {
      setPasswordError('New passwords do not match.');
      return;
    }
    const result = await changePassword(currentPassword, newPassword);
    if (result.ok) {
      setPasswordMessage('Password updated.');
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
    } else {
      setPasswordError(result.error);
    }
  };

  return (
    <motionless className="page">
      <header className="page-header">
        <h2>Settings</h2>
        {session && (
          <p className="muted">
            Signed in as <strong>{session.username}</strong> ({session.role})
          </p>
        )}
      </header>

      <section className="card">
        <h3 className="section-title">Daily rules</h3>
        <label className="field">
          <span>Daily quota (%)</span>
          <input
            type="number"
            min={50}
            max={100}
            value={state.settings.dailyQuotaPercent}
            onChange={(e) =>
              updateSettings({ dailyQuotaPercent: Number(e.target.value) })
            }
          />
        </label>
        <label className="field">
          <span>Reset hour (0–23)</span>
          <input
            type="number"
            min={0}
            max={23}
            value={state.settings.resetHour}
            onChange={(e) => updateSettings({ resetHour: Number(e.target.value) })}
          />
        </label>
        <p className="muted">
          The day starts after this hour. The plan regenerates automatically.
        </p>
      </section>

      <section className="card">
        <h3 className="section-title">Change password</h3>
        <form onSubmit={handlePasswordChange}>
          <label className="field">
            <span>Current password</span>
            <input
              type="password"
              autoComplete="current-password"
              value={currentPassword}
              onChange={(e) => setCurrentPassword(e.target.value)}
              required
            />
          </label>
          <label className="field">
            <span>New password</span>
            <input
              type="password"
              autoComplete="new-password"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              minLength={6}
              required
            />
          </label>
          <label className="field">
            <span>Confirm new password</span>
            <input
              type="password"
              autoComplete="new-password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              minLength={6}
              required
            />
          </label>
          {passwordError && (
            <p className="login-error" role="alert">
              {passwordError}
            </p>
          )}
          {passwordMessage && <p className="notice">{passwordMessage}</p>}
          <button type="submit" className="btn btn--primary btn--block">
            Update password
          </button>
        </form>
      </section>

      {session?.role === 'admin' && (
        <section className="card">
          <h3 className="section-title">Administration</h3>
          <p className="muted">
            Create categories and tasks for all users.
          </p>
          <Link to="/admin" className="btn btn--primary btn--block">
            Open admin panel
          </Link>
        </section>
      )}

      <section className="card">
        <button type="button" className="btn btn--ghost btn--block" onClick={logout}>
          Sign out
        </button>
        <button type="button" className="btn btn--danger" onClick={resetAll}>
          Reset game data
        </button>
        <p className="muted">
          Reset clears tasks, progress, and plans but keeps user accounts. To
          remove old French sample data, reset here or clear{' '}
          <code>sissy-training-state</code> in browser storage.
        </p>
      </section>
    </motionless>
  );
}

